"""Extracts the 8x8 bitmap font that ships with SDL3 (SDL_render_debug_font.h) into code_runtime/source/font8x8.inc.

The font itself is the public domain IBM VGA font, as redistributed by SDL.

Usage: extract_font.py <path to SDL_render_debug_font.h> <output.inc>
"""
import re
import sys

source = open(sys.argv[1], encoding="utf-8").read()
start = source.index("SDL_RenderDebugTextFontData[] = {")
end = source.index("};", start)
rows = [int(m.group(1), 16) for m in re.finditer(r"^\s*0x([0-9a-fA-F]{2}),", source[start:end], re.M)]
assert len(rows) % 8 == 0, "font data is not made of 8 row glyphs"

with open(sys.argv[2], "w", newline="\n") as out:
    out.write("// Generated by tools/extract_font.py, do not edit.\n")
    out.write("// 8x8 public domain IBM VGA font (via SDL3), one byte per row, LSB is the left-most pixel.\n")
    out.write("// Glyphs start at character code 33 ('!') and are consecutive.\n")
    out.write("#define BB_FONT_FIRST_GLYPH 33\n")
    out.write("#define BB_FONT_GLYPHS %d\n" % (len(rows) // 8))
    out.write("static const unsigned char bb_font_data[] = {\n")
    for i in range(0, len(rows), 8):
        out.write("\t" + ", ".join("0x%02x" % r for r in rows[i:i + 8]) + ",\n")
    out.write("};\n")
